mapper.select:
select * from MsgLog where operationType=#{operationType} and ledgerDate=#{ledgerDate}

	 and portfolio in

	#{item}

select msglog0_.operationType as operation, msglog0_.status as status, count(*) as totalnum from MsgLog msglog0_ where ( msglog0_.operationType in ( 1 , 2 , 3 ) ) and msglog0_.ledgerDate=#{ledgerDate} and msglog0_.ingore=0 and ( msglog0_.sourceid in ( select distinct portfolioi1_.InterfaceSourceID from PortfolioInterfaceMap portfolioi1_ where portfolioi1_.portfolio in
#{item}
) ) group by msglog0_.operationType , msglog0_.status

select msglog0_.operationType as operation, msglog0_.status as status, count(*) as totalnum from MsgLog msglog0_ where ( msglog0_.operationType in ( 4 , 5 , 6, 7 , 8 , 9 ) ) and msglog0_.ledgerDate=#{ledgerDate} and msglog0_.ingore=0 and ( msglog0_.sourceid in ( select distinct portfolioi1_.InterfaceSourceID from PortfolioInterfaceMap portfolioi1_ where portfolioi1_.portfolio in
#{item}
) ) group by msglog0_.operationType , msglog0_.status
